# Fix blurry text on high-DPI displays while maintaining proper size
try:
    # Force highest DPI awareness (Per-Monitor V2)
    ctypes.windll.shcore.SetProcessDpiAwareness(2)
except:
    try:
        ctypes.windll.user32.SetProcessDPIAware()
    except:
        pass

# Get the DPI scaling factor
try:
    dpi = ctypes.windll.user32.GetDpiForSystem()
    SCALE_FACTOR = dpi / 75
except:
    SCALE_FACTOR = 0.8

# Get screen dimensions so we can cap the game viewport to fit
try:
    _screen_w = ctypes.windll.user32.GetSystemMetrics(0)  # SM_CXSCREEN
    _screen_h = ctypes.windll.user32.GetSystemMetrics(1)  # SM_CYSCREEN
except:
    _screen_w, _screen_h = 1920, 1080

# ---------- Music system ----------
_music_enabled   = False
_music_stop_evt  = threading.Event()
_music_thread    = None
_music_audio_cache = None   # generated once, reused

def _get_f(m): return 440 * (2 ** ((m - 69) / 12))

def _generate_music_bytes():
    global _music_audio_cache
    if _music_audio_cache is not None:
        return _music_audio_cache
    RATE = 44100; BPM = 70; BEAT = 60 / BPM; AMP = 7500
    score = [
        ([43,55,71],3.0),([74],1.0),([43,55,76],4.0),
        ([42,54,69],3.0),([73],1.0),([42,54,74],4.0),
        ([43,55,81],2.0),([83],2.0),([42,54,78],4.0),
        ([40,52,74],2.0),([76],2.0),([38,50,78],4.0),
        ([43,55,78],2.0),([81],2.0),([42,54,76],4.0),
        ([40,52,74],2.0),([71],2.0),([38,50,69],2.0),([66],2.0),
        ([43,55,74],1.0),([76],1.0),([78],1.0),([81],1.0),
        ([42,54,78],2.0),([76],2.0),([43,55,71,74],8.0),
    ]
    buf_io = io.BytesIO()
    with wave.open(buf_io, 'wb') as wf:
        wf.setnchannels(1); wf.setsampwidth(2); wf.setframerate(RATE)
        frames = []
        for notes, beats in score:
            n = int(RATE * beats * BEAT)
            buf = [0.0] * n
            for idx, m in enumerate(notes):
                freq = _get_f(m)
                off  = int(idx * 0.03 * RATE)
                for i in range(off, n):
                    t   = (i - off) / RATE
                    env = math.exp(-1.5 * (i - off) / (n - off))
                    if t < 0.05: env *= t / 0.05
                    buf[i] += (math.sin(2*math.pi*freq*t) + 0.15*math.sin(4*math.pi*freq*t)) * env
            for v in buf:
                c = max(-1.0, min(1.0, v / (len(notes) * 1.2)))
                frames.append(struct.pack('<h', int(c * AMP)))
        wf.writeframes(b''.join(frames))
    _music_audio_cache = buf_io.getvalue()
    return _music_audio_cache

def _music_worker():
    try:
        import winsound
        data = _generate_music_bytes()
        while not _music_stop_evt.is_set():
            winsound.PlaySound(data, winsound.SND_MEMORY | winsound.SND_NODEFAULT)
    except Exception:
        pass

def music_start():
    global _music_thread
    if not _music_enabled:
        return
    if _music_thread and _music_thread.is_alive():
        return
    _music_stop_evt.clear()
    _music_thread = threading.Thread(target=_music_worker, daemon=True)
    _music_thread.start()

def music_stop():
    _music_stop_evt.set()
    try:
        import winsound
        winsound.PlaySound(None, winsound.SND_PURGE)
    except Exception:
        pass

def _make_settings_overlay(parent_frame, anchor_widget=None):
    """Build a settings panel as a Frame overlay on parent_frame.
    If anchor_widget is given the overlay sits just below it; otherwise top-right.
    Returns the overlay frame (caller may keep a ref to destroy it later).
    """
    global _music_enabled

    overlay = tk.Frame(parent_frame, bg='#1a1a2e', bd=2, relief='ridge')
    overlay.place(relx=1.0, rely=0.0, anchor='ne', x=-8, y=42)

    tk.Label(overlay, text="⚙️  Settings", font=("Arial", 13, "bold"),
             bg='#1a1a2e', fg='#ccaaff').pack(padx=18, pady=(12, 6))

    row = tk.Frame(overlay, bg='#1a1a2e')
    row.pack(padx=18, pady=(0, 8))
    tk.Label(row, text="🎵  Music", font=("Arial", 11),
             bg='#1a1a2e', fg='#dddddd').pack(side='left', padx=(0, 14))

    def toggle():
        global _music_enabled
        _music_enabled = not _music_enabled
        tog_btn.config(text=" ON " if _music_enabled else " OFF",
                       bg='#2a6a2a' if _music_enabled else '#5a2a2a')
        if _music_enabled:
            music_start()
        else:
            threading.Thread(target=music_stop, daemon=True).start()

    tog_btn = tk.Button(row, text=" ON " if _music_enabled else " OFF",
                        font=("Arial", 10, "bold"), width=5,
                        bg='#2a6a2a' if _music_enabled else '#5a2a2a',
                        fg='white', bd=0, pady=3, cursor='hand2', command=toggle)
    tog_btn.pack(side='left')

    def close():
        overlay.destroy()

    tk.Button(overlay, text="✕  Close", font=("Arial", 9),
              bg='#2a2a3a', fg='#aaaacc', activebackground='#3a3a5a',
              bd=0, padx=14, pady=4, cursor='hand2',
              command=close).pack(padx=18, pady=(0, 12))

    return overlay


