            # ── Small cauldron right side, mid-room ──────────────────────
            cd2_x=W-ow-70; cd2_y=H//2+20
            objs+=[{'type':'big_cauldron','x':cd2_x,'y':cd2_y,'r':38,'liq_color':'#aa44ff'},
                   conly(cd2_x-48,cd2_y-24,96,80)]
            # ── Central map table with open scroll ───────────────────────
            mt_w=160; mt_h=90
